(function(){"use strict";app.factory("proveedorService",function(t){const e="Compra/Proveedor/",o={},n=t.get("mainService");return o.get=function(t){const o={...t,tipo:1};return n.getData("get",`${e}?json=${JSON.stringify(o)}`,null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let{proveedores:e}=JSON.parse(t.payload);return e}})},o.getDataForm=function(){let t={tipo:3};return n.getData("get",`${e}?json=${JSON.stringify(t)}`,null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let{tiposIdentificacion:e,subcontribuyentes:o,tiemposCredito:n,tiposEntidad:r,tiposProveedor:i,ciudades:a}=JSON.parse(t.payload);return{tiposIdentificacion:e,subcontribuyentes:o,tiemposCredito:n,tiposEntidad:r,tiposProveedor:i,ciudades:a}}})},o.getId=function(t){let o={id:t,tipo:2};return n.getData("get",`${e}?json=${JSON.stringify(o)}`,null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload),o=e.proveedor[0];return{...o,correos:o.correo?o.correo.split(";"):[],telefonos:o.telefonos?o.telefonos.split(";"):[]}}})},o.checkByID=function(t){let o={tipo:4,identificacion:t};return n.getData("get",`${e}?json=${JSON.stringify(o)}`,null,!0).then(t=>{if(console.log(t),"0"===t.code)return{idProveedor:0,idTiempoCredito:0};if("1"===t.code){let e=JSON.parse(t.payload);console.log(e)}})},o.post=function(t){return n.getData("post",`${e}`,{data:t},!0)},o.put=function(t,o){return n.getData("put",`${e}${t}`,{data:o},!0)},o.delete=function(t){return n.getData("delete",e+t,null,!0)},o}),app.factory("categoriaCompraService",function(t){const e="Compra/CategoriaCompra/",o=t.get("mainService"),n={get:t=>o.getData("get",e+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload);return e}}),post:t=>o.getData("post",e+"?json="+JSON.stringify(t),null,!0),put:(t,n)=>o.getData("put",e+t+"?json="+JSON.stringify(n),null,!0),delete:t=>o.getData("delete",e+""+t,null,!0)};return n})})(window.angular);